// Reads PROJECT-STATUS.md's "- [ ]" / "- [x]" checklist items (grouped by
// the nearest ## or ### heading) plus the last 7 days of commits, and
// builds a plain-language weekly status email. No fabricated content —
// everything here is pulled directly from the doc and the commit log.

const mdRaw = $('Fetch PROJECT-STATUS.md').first().json;
const md = typeof mdRaw === 'string' ? mdRaw : (mdRaw.data || JSON.stringify(mdRaw));

let commits = [];
for (const it of $('Fetch Recent Commits').all()) {
  if (Array.isArray(it.json)) commits.push(...it.json);
  else if (it.json && it.json.commit) commits.push(it.json);
}

function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Parse checklist items, joining indented continuation lines onto the
// previous bullet so multi-line items don't get truncated.
const lines = md.split('\n');
let currentSection = '';
let current = null;
const items = [];
for (const rawLine of lines) {
  const heading = rawLine.match(/^#{2,3}\s+(.*)/);
  if (heading) { currentSection = heading[1].trim(); current = null; continue; }
  const check = rawLine.match(/^-\s\[( |x)\]\s+(.*)/i);
  if (check) {
    current = { done: check[1].toLowerCase() === 'x', section: currentSection, text: check[2].trim() };
    items.push(current);
    continue;
  }
  const cont = rawLine.match(/^\s{4,}(\S.*)/);
  if (cont && current) current.text += ' ' + cont[1].trim();
  else current = null;
}

const pending = items.filter((i) => !i.done);
const done = items.filter((i) => i.done);

const pendingBySection = {};
for (const p of pending) (pendingBySection[p.section] = pendingBySection[p.section] || []).push(p.text);

let pendingHtml = '';
for (const [section, texts] of Object.entries(pendingBySection)) {
  pendingHtml += `<h3>${escapeHtml(section)}</h3><ul>${texts.map((t) => `<li>${escapeHtml(t)}</li>`).join('')}</ul>`;
}
if (!pendingHtml) pendingHtml = '<p>Nothing pending — every tracked item is checked off.</p>';

const doneHtml = done.length
  ? `<ul>${done.map((d) => `<li>${escapeHtml(d.text)}</li>`).join('')}</ul>`
  : '<p>None checked off yet.</p>';

const commitLines = commits.slice(0, 20).map((c) => {
  const msg = ((c.commit && c.commit.message) || '').split('\n')[0];
  const author = (c.commit && c.commit.author && c.commit.author.name) || 'unknown';
  const dateStr = (c.commit && c.commit.author && c.commit.author.date) || '';
  const shortDate = dateStr ? new Date(dateStr).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' }) : '';
  return `${shortDate} — ${msg} (${author})`;
});
const commitsHtml = commitLines.length
  ? `<ul>${commitLines.map((c) => `<li>${escapeHtml(c)}</li>`).join('')}</ul>`
  : '<p>No commits pushed to main in the last 7 days.</p>';

const html = `
<h2>Openmind Project — Weekly Status</h2>
<p>${done.length} of ${done.length + pending.length} tracked items done. Full doc: <a href="https://github.com/inder20216/openmind360/blob/main/PROJECT-STATUS.md">PROJECT-STATUS.md</a></p>
<h2>Still Pending</h2>
${pendingHtml}
<h2>Completed</h2>
${doneHtml}
<h2>Commits in the Last 7 Days</h2>
${commitsHtml}
`;

return [{ json: { html, subject: `Openmind Project — Weekly Status (${new Date().toLocaleDateString('en-IN')})` } }];
